@router.get(
    "/courses/{slug}/units/{unit_id}/flashcard-gen-status",
    response_class=HTMLResponse,
)
async def flashcard_gen_status(
    request: Request,
    slug: str,
    unit_id: int,
    db: Session = Depends(get_db),
):
    from app.models import Flashcard
    from datetime import datetime, timezone, timedelta

    get_course_for_user(request, db, slug)
    recent = (
        db.query(Flashcard)
        .filter(
            Flashcard.unit_id == unit_id,
            Flashcard.created_at >= datetime.now(timezone.utc) - timedelta(minutes=5),
        )
        .count()
    )
    if recent > 0:
        return HTMLResponse(
            f'<p style="font-size:13px; color:var(--mastered);">'
            f'{recent} flashcards generated — <a href="" onclick="location.reload();return false;">refresh to review</a></p>'
        )
    return HTMLResponse(
        '<p id="flashcard-gen-status" '
        f'hx-get="/courses/{slug}/units/{unit_id}/flashcard-gen-status" '
        'hx-trigger="every 3s" '
        'hx-swap="outerHTML" '
        'style="font-size:13px; color:var(--text-secondary);">'
        "Generating flashcards…</p>"
    )

